/* Keyboard, paste and recoverable operations for the purchase prototype. */
const work={undo:[],pendingDelete:new Set(),deleteVersions:{},quick:'',anchor:null,batching:false};
const workCopy=x=>JSON.parse(JSON.stringify(x));
function workSnapshot(){return {drafts:workCopy([...bulkDrafts]),splits:workCopy([...planning.splits]),trials:workCopy(ROWS.filter(r=>r.__trialNew)),deleted:[...work.pendingDelete],deleteVersions:workCopy(work.deleteVersions)}}
function workRecord(label,before){const after=workSnapshot();if(JSON.stringify(before)!==JSON.stringify(after)){const token=label.startsWith('Sửa ')?work.editToken:null,last=work.undo.at(-1);if(token&&last?.token===token&&last.label===label){}else work.undo.push({label,before,token});if(work.undo.length>60)work.undo.shift()}workPersist()}
function workPersist(){try{sessionStorage.setItem('purchase:work:v1',JSON.stringify({rows:ROWS,logs:LOG,deleteVersions:work.deleteVersions,undo:work.undo,pendingDelete:[...work.pendingDelete],deleted:ROWS.filter(r=>r.__deleted),quick:work.quick}))}catch{}}
function workDo(label,fn){const before=workSnapshot();work.batching=true;try{fn()}finally{work.batching=false;workRecord(label,before);render()}}
mainRows.addEventListener('focusin',()=>{work.editToken=(work.editToken||0)+1},true);
const workStage=stagePlanningCell;stagePlanningCell=function(...args){if(work.batching)return workStage(...args);const before=workSnapshot(),ok=workStage(...args);if(ok)workRecord('Sửa '+(colByKey(args[1])?.l||'cont'),before);return ok};
const workAddDraft=saveDraft;saveDraft=function(){workDo('Thêm mã',()=>workAddDraft())};
mainRows.addEventListener('change',e=>{const id=e.target.dataset.splitQty||e.target.dataset.splitCont;if(!id)return;e.stopImmediatePropagation();const part=planning.splits.get(Number(id));if(!part)return;workDo(e.target.dataset.splitQty?'Sửa số thùng mã con':'Chuyển cont mã con',()=>{if(e.target.dataset.splitQty)part.quantity=e.target.value===''?null:Number(e.target.value);else part.destinationId=e.target.value===''?null:Number(e.target.value);bulkPending=null})},true);
const workSplit=openPlanningTransfer;openPlanningTransfer=function(id){workDo('Tách dòng',()=>workSplit(id))};openSplit=openPlanningTransfer;
const workRows=planningRows;planningRows=function(){return workRows().filter(r=>!r.__deleted&&!work.pendingDelete.has(r.id))};
const workFiltered=filtered;filtered=function(){return workFiltered().filter(r=>{if(work.quick==='mine')return r.buyer===ME.name;if(work.quick==='eta')return !r.etaNote;if(work.quick==='measure')return !(r.kgPerCarton>0&&r.m3PerCarton>0);return true})};
function workSelected(){return [...state.picked].map(id=>ROWS.find(r=>r.id===id&&!r.__deleted)).filter(Boolean)}
function workRequireSelection(){const rows=workSelected();if(!rows.length){toast('Bấm Sửa hàng loạt và chọn dòng trước.',true);return null}return rows}
function workUndo(){work.editToken=(work.editToken||0)+1;const last=work.undo.at(-1);if(!last){toast('Chưa có thao tác để hoàn tác.');return}if(last.saved){const conflicts=last.changed.some(x=>JSON.stringify(ROWS.find(r=>r.id===x.id)||null)!==JSON.stringify(x.after));if(conflicts){toast('Dòng đã thay đổi sau thao tác này; không thể hoàn tác để tránh ghi đè.',true);return}last.changed.forEach(x=>{const i=ROWS.findIndex(r=>r.id===x.id);if(x.before){const restored={...workCopy(x.before),v:(x.after?.v||x.before.v)+1};if(i>=0)ROWS[i]=restored;else ROWS.push(restored)}else if(i>=0)ROWS.splice(i,1)});logIt({action:'undo',summary:'Hoàn tác '+last.label,detail:last.changed.map(x=>({label:x.before?.rowKey||x.after?.rowKey,old:'Sau thao tác',new:'Khôi phục trước thao tác'}))})}else{const b=last.before;bulkDrafts.clear();b.drafts.forEach(([id,d])=>bulkDrafts.set(id,d));planning.splits.clear();b.splits.forEach(([id,p])=>planning.splits.set(id,p));ROWS=ROWS.filter(r=>!r.__trialNew);ROWS.push(...workCopy(b.trials));work.pendingDelete=new Set(b.deleted);work.deleteVersions=b.deleteVersions||{}}work.undo.pop();if(last.saved){for(const frame of work.undo.filter(x=>x.saved)){frame.changed.forEach(x=>{const current=ROWS.find(r=>r.id===x.id)||null;if(last.changed.some(y=>y.id===x.id)&&x.after&&current){const a={...x.after},b={...current};delete a.v;delete b.v;if(JSON.stringify(a)===JSON.stringify(b))x.after=workCopy(current)}})}}bulkPending=null;workPersist();render();toast('Đã hoàn tác: '+last.label)}
function workSavedFrame(label,before){const ids=new Set([...before.map(r=>r.id),...ROWS.map(r=>r.id)]),changed=[];ids.forEach(id=>{const b=before.find(r=>r.id===id)||null,a=ROWS.find(r=>r.id===id)||null;if(JSON.stringify(b)!==JSON.stringify(a))changed.push({id,before:b,after:workCopy(a)})});if(changed.length){work.undo=work.undo.filter(x=>x.saved);work.undo.push({saved:true,label,changed});if(work.undo.length>60)work.undo.shift();workPersist()}}
function workDelete(){const rows=workRequireSelection();if(!rows)return;bulkPanel.hidden=false;bulkPanel.innerHTML='<h2>Xóa '+rows.length+' dòng?</h2><p>Chỉ số cont sẽ tính lại. Dòng đã lưu được giữ trong Đã xóa để khôi phục.</p><button id="workDeleteConfirm" class="btn-danger">Đánh dấu xóa</button>';document.getElementById('workDeleteConfirm').onclick=()=>workDo('Đánh dấu xóa',()=>{rows.forEach(r=>{work.pendingDelete.add(r.id);work.deleteVersions[r.id]=r.v;planning.splits.delete(r.id)});state.picked.clear();bulkPending=null;bulkPanel.hidden=true})}
function workTrash(){const rows=ROWS.filter(r=>r.__deleted);bulkPanel.hidden=false;bulkPanel.innerHTML='<h2>Đã xóa · '+rows.length+' dòng</h2>'+rows.map(r=>'<p>'+pe(r.rowKey)+' · '+pe(r.productCode)+' <button data-work-restore="'+r.id+'">Khôi phục</button></p>').join('');bulkPanel.querySelectorAll('[data-work-restore]').forEach(b=>b.onclick=()=>{const r=ROWS.find(r=>r.id===Number(b.dataset.workRestore));const before=workCopy(ROWS);delete r.__deleted;r.v++;logIt({action:'restore',rowKey:r.rowKey,orderId:r.id,summary:'Khôi phục dòng',new:r.productCode});workSavedFrame('Khôi phục dòng',before);render();workTrash()})}
function workReorder(){const selected=workRequireSelection();if(!selected)return;workDo('Đặt lại '+selected.length+' mã',()=>{selected.forEach(r=>{const source=ROWS.filter(x=>!x.__deleted&&!x.__trialNew&&x.productCode===r.productCode).sort((a,b)=>String(b.listedAt||'').localeCompare(String(a.listedAt||''))||b.id-a.id)[0]||r;const copy={...workCopy(source),id:--planning.seq,rowKey:'MỚI '+(-planning.seq),v:1,contId:planning.target,listedAt:new Date().toLocaleDateString('sv-SE'),__trialNew:true};['rootKey','rootCartons','splitFromKey','splitDisplayOrder','splitCostSnapshot','netLocked','netLockedAll'].forEach(k=>delete copy[k]);copy.shippedNote='';copy.arrivedNote='';ROWS.unshift(copy)});state.picked.clear()})}
function workMove(){const rows=workRequireSelection();if(!rows)return;bulkPanel.hidden=false;bulkPanel.innerHTML='<h2>Chuyển '+rows.length+' dòng sang cont</h2><select id="workMoveTarget"><option value="">Cont chờ xếp</option>'+CONTAINERS.map(c=>'<option value="'+c.id+'">'+pe(c.name)+'</option>').join('')+'</select> <button id="workMoveApply">Chọn cont</button>';document.getElementById('workMoveApply').onclick=()=>{const target=document.getElementById('workMoveTarget').value;workDo('Chuyển cont hàng loạt',()=>{const mode=bulkMode;bulkMode=false;try{rows.forEach(r=>stagePlanningCell(r,'contId',target===''?null:Number(target)))}finally{bulkMode=mode}bulkPanel.hidden=true})}}
function workIssues(){const errors=[],warnings=[];planningDirtyIds().forEach(id=>{const raw=ROWS.find(r=>r.id===id);if(!raw||work.pendingDelete.has(id))return;const r={...raw,...bulkDrafts.get(id)?.changes};['productCode','productName'].forEach(k=>{if(!String(r[k]||'').trim())errors.push({id,key:k,text:(colByKey(k)?.l||k)+' còn trống'})});['cartonCount','qtyPerCarton'].forEach(k=>{if(!Number.isSafeInteger(r[k])||r[k]<=0)errors.push({id,key:k,text:(colByKey(k)?.l||k)+' phải là số nguyên dương'})});for(const key of PurchaseCalculations.issues(r).filter(k=>!['qtyPerCarton','cartonCount'].includes(k)))errors.push({id,key,text:(colByKey(key)?.l||key)+' không hợp lệ hoặc vượt giới hạn tính toán'});const p=planning.splits.get(id);if(p&&(!Number.isSafeInteger(p.quantity)||p.quantity<=0))errors.push({id:'split-'+id,key:'cartonCount',text:'Mã con chưa có số thùng hợp lệ'});if(!(r.kgPerCarton>0&&r.m3PerCarton>0))warnings.push({id,key:'kgPerCarton',text:'Thiếu số đo, chưa đủ cơ sở đánh giá tải/khối'})});return {errors,warnings}}
function workShowIssues(){const result=workIssues();bulkPanel.hidden=false;bulkPanel.innerHTML='<h2>Kiểm tra dữ liệu</h2><p>'+result.errors.length+' lỗi cần sửa · '+result.warnings.length+' cảnh báo</p>'+[...result.errors,...result.warnings].map((x,i)=>'<p><button data-work-issue="'+i+'">'+pe(x.text)+'</button></p>').join('');const list=[...result.errors,...result.warnings];bulkPanel.querySelectorAll('[data-work-issue]').forEach(b=>b.onclick=()=>{const issue=list[+b.dataset.workIssue];planning.onlyDirty=true;work.quick='';state.visible.add(issue.key);const rows=filtered();state.page=Math.floor(Math.max(0,rows.findIndex(r=>String(r.id)===String(issue.id)))/Number(pageSize.value||50))+1;render();const cell=mainRows.querySelector('tr[data-id="'+issue.id+'"] [data-k="'+issue.key+'"]');cell?.scrollIntoView({block:'center'});cell?.click()});return result}
const workCheck=planningCheck;planningCheck=function(){if(workIssues().errors.length){workShowIssues();return}if(work.pendingDelete.size&&!planningDirtyIds().size){bulkPending=[];bulkPanel.hidden=false;bulkPanel.innerHTML='<h2>Xác nhận xóa '+work.pendingDelete.size+' dòng</h2><button id="workSaveDelete">Lưu thay đổi</button>';document.getElementById('workSaveDelete').onclick=bulkCommit;return}workCheck();if(work.pendingDelete.size)bulkPanel.insertAdjacentHTML('afterbegin','<p>Xóa '+work.pendingDelete.size+' dòng; có thể khôi phục trong Đã xóa.</p>')};
const workCommit=bulkCommit;bulkCommit=function(){if(bulkPending==null)return;if([...work.pendingDelete].some(id=>ROWS.find(r=>r.id===id)?.v!==work.deleteVersions[id])){toast('Dòng cần xóa đã được sửa; chưa lưu. Hủy và chọn lại dòng để kiểm tra.',true);return}if(workIssues().errors.length){workShowIssues();return}const before=workCopy(ROWS);const temporary=ROWS.filter(r=>r.__trialNew&&work.pendingDelete.has(r.id));temporary.forEach(r=>{bulkDrafts.delete(r.id);work.pendingDelete.delete(r.id)});ROWS=ROWS.filter(r=>!temporary.includes(r));bulkPending=bulkPending.filter(x=>!temporary.some(r=>r.id===x.id));if(bulkPending.length||ROWS.some(r=>r.__trialNew)||planning.splits.size)workCommit();const failed=bulkDrafts.size||planning.splits.size;if(!failed){work.pendingDelete.forEach(id=>{const r=ROWS.find(r=>r.id===id);if(!r)return;r.__deleted=true;r.v++;logIt({action:'delete',orderId:r.id,rowKey:r.rowKey,summary:'Xóa dòng',old:r.productCode})});work.pendingDelete.clear();bulkPending=null;bulkPanel.hidden=true;workSavedFrame('Lưu thay đổi',before)}render()};
const workCancel=bulkCancel;bulkCancel=function(){workDo('Hủy thay đổi',()=>{work.pendingDelete.clear();workCancel()})};
const workToolbar=bulkToolbar;bulkToolbar=function(){workToolbar();const root=document.getElementById('bulkActions');const add=(label,fn,disabled=false)=>{const b=document.createElement('button');b.className='ghost';b.textContent=label;b.disabled=disabled;b.onclick=fn;menu.append(b)};const undo=document.createElement('button');undo.className='ghost';undo.textContent='Hoàn tác';undo.disabled=!work.undo.length;undo.onclick=workUndo;root.append(undo);const details=document.createElement('details');details.className='work-menu';details.innerHTML='<summary>Tác vụ ▾</summary>';const menu=document.createElement('div');details.append(menu);root.append(details);add('Đặt lại',workReorder);add('Chuyển cont',workMove);add('Xóa dòng',workDelete);add('Đã xóa ('+ROWS.filter(r=>r.__deleted).length+')',workTrash);add('Kiểm tra',workShowIssues);if(work.pendingDelete.size&&!planningDirtyIds().size)add('Lưu xóa ('+work.pendingDelete.size+')',planningCheck);const filter=document.createElement('select');filter.setAttribute('aria-label','Bộ lọc nhanh');filter.innerHTML=[['','Lọc nhanh'],['mine','Mã tôi đặt'],['eta','Thiếu ngày dự kiến'],['measure','Thiếu số đo']].map(([v,l])=>'<option value="'+v+'" '+(v===work.quick?'selected':'')+'>'+l+'</option>').join('');filter.onchange=()=>{work.quick=filter.value;state.page=1;workPersist();render()};root.append(filter)};
mainRows.addEventListener('click',e=>{const td=e.target.closest('td[data-k]');if(td)work.anchor={id:td.closest('tr').dataset.id,key:td.dataset.k}},true);
function workNavigate(id,key,delta,vertical){const cells=[...mainRows.querySelectorAll('td[data-k]')].filter(td=>{const c=colByKey(td.dataset.k);return c&&!c.d&&!c.m&&(c.e||c.k==='productCode')});const current=cells.find(td=>td.closest('tr').dataset.id===id&&td.dataset.k===key);let next;if(vertical){const rows=[...mainRows.querySelectorAll('tr[data-id]')],i=rows.findIndex(r=>r.dataset.id===id);next=rows[i+delta]?.querySelector('[data-k="'+key+'"]')}else next=cells[cells.indexOf(current)+delta];if(next){next.click();next.querySelector('input,select')?.focus()}}
mainRows.addEventListener('keydown',e=>{if(e.key!=='Enter'&&e.key!=='Tab')return;const td=e.target.closest('td[data-k]');if(!td)return;const id=td.closest('tr').dataset.id,key=td.dataset.k;e.preventDefault();e.stopImmediatePropagation();if(e.target.matches('input,select')){e.target.dispatchEvent(new Event('change',{bubbles:true}));e.target.blur()}workNavigate(id,key,e.shiftKey?-1:1,e.key==='Enter')},true);
function workPaste(text,anchor=work.anchor){if(!anchor)throw Error('Chọn ô bắt đầu dán trước.');const matrix=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(line=>line.split('\t'));if(matrix.length>500)throw Error('Tối đa 500 dòng mỗi lần dán.');const rows=filtered(),start=rows.findIndex(r=>String(r.id)===String(anchor.id)),cols=COLS.filter(c=>state.visible.has(c.k)),colStart=cols.findIndex(c=>c.k===anchor.key),ops=[],errors=[];matrix.forEach((line,i)=>line.forEach((raw,j)=>{const r=rows[start+i],c=cols[colStart+j];if(!r||!c){errors.push('Vùng dán vượt bảng');return}if(c.d||c.m||!c.e&&c.k!=='productCode'||c.k==='container'||r.__splitPreview){errors.push('Không dán được vào '+c.l);return}let val=raw.trim();if(isNum(c.t)){val=val===''?null:PurchaseCalculations.parse(val);if(val!=null&&(!Number.isFinite(val)||val<0)||['cartonCount','qtyPerCarton'].includes(c.k)&&(!Number.isSafeInteger(val)||val<=0))errors.push(c.l+': số không hợp lệ')}else if(c.t==='datetime'&&val){val=PurchaseExcel.dateTimeValue(val);if(!val)errors.push(c.l+': ngày không hợp lệ')}if(['productCode','productName'].includes(c.k)&&!val)errors.push(c.l+': không được trống');ops.push({id:r.id,key:c.k,value:val})}));if(errors.length)throw Error([...new Set(errors)].join(' · '));workDo('Dán '+ops.length+' ô từ Excel',()=>{const mode=bulkMode;bulkMode=false;try{ops.forEach(x=>stagePlanningCell(ROWS.find(r=>r.id===x.id),x.key,x.value))}finally{bulkMode=mode}});return ops.length}
mainRows.addEventListener('paste',e=>{const text=e.clipboardData?.getData('text/plain');if(!text||!/[\t\n]/.test(text))return;e.preventDefault();try{workPaste(text);toast('Đã dán vào các ô; chưa lưu.')}catch(error){toast('Chưa dán: '+error.message,true)}});
try{const saved=JSON.parse(sessionStorage.getItem('purchase:work:v1')||'null');if(saved){if(saved.logs){LOG.splice(0,LOG.length,...saved.logs.map(l=>({...l,at:new Date(l.at)})));logSeq=Math.max(logSeq,...LOG.map(l=>l.lid||0))}if(saved.rows){ROWS=saved.rows;rowSeq=Math.max(rowSeq,...ROWS.map(r=>Number(r.id)||0));keySeq=Math.max(keySeq,...ROWS.map(r=>Number(String(r.rowKey).match(/^D(\d+)/)?.[1])||0));planning.seq=Math.min(planning.seq,...ROWS.filter(r=>r.__trialNew).map(r=>r.id))}work.deleteVersions=saved.deleteVersions||{};work.undo=saved.undo||[];work.pendingDelete=new Set(saved.pendingDelete||[]);work.quick=saved.quick||'';(saved.deleted||[]).forEach(r=>{const i=ROWS.findIndex(x=>x.id===r.id);if(i>=0)ROWS[i]=r;else ROWS.push(r)})}}catch{}
window.addEventListener('beforeunload',e=>{if(work.pendingDelete.size){e.preventDefault();e.returnValue=''}});
render();
